package com.xyzterm.terminal;

import java.util.concurrent.atomic.AtomicLong;

/** Runs `PortableLogicKt` and its Rust port side by side. Generated by rust-anything: call it in place of `PortableLogicKt`. */
public final class PortableLogicKtShadow {
    private PortableLogicKtShadow() {}

    private static final String MODE = ("original".equals(System.getenv("RUST_ANYTHING_UNIT_TERMINAL")) ? "old" : System.getProperty("rust-anything.mode", "shadow"));
    public static final AtomicLong CALLS = new AtomicLong();
    public static final AtomicLong MISMATCHES = new AtomicLong();

    private static void compare(String name, Object expected, Object actual) {
        CALLS.incrementAndGet();
        if (actual instanceof Throwable || !rustanything.RustAnythingJson.write(expected).equals(rustanything.RustAnythingJson.write(actual))) {
            if (MISMATCHES.incrementAndGet() <= 10) {
                System.err.println("[rust-anything] mismatch in " + name + ": expected " + expected + ", got " + actual);
            }
        }
    }

    @SuppressWarnings("unchecked")
    public static String detectBackupLayoutName(String entriesJoined) {
        if (MODE.equals("new")) {
            return (String) rustanything.TerminalRsNative.call_detectBackupLayoutName(entriesJoined);
        }
        String expected = PortableLogicKt.detectBackupLayoutName(entriesJoined);
        if (!MODE.equals("old")) {
            Object actual;
            try {
                actual = rustanything.TerminalRsNative.call_detectBackupLayoutName(entriesJoined);
            } catch (RuntimeException e) {
                actual = e;
            }
            compare("detectBackupLayoutName", expected, actual);
        }
        return expected;
    }

    @SuppressWarnings("unchecked")
    public static boolean isWellFormedHost(String path) {
        if (MODE.equals("new")) {
            return (Boolean) rustanything.TerminalRsNative.call_isWellFormedHost(path);
        }
        boolean expected = PortableLogicKt.isWellFormedHost(path);
        if (!MODE.equals("old")) {
            Object actual;
            try {
                actual = rustanything.TerminalRsNative.call_isWellFormedHost(path);
            } catch (RuntimeException e) {
                actual = e;
            }
            compare("isWellFormedHost", expected, actual);
        }
        return expected;
    }

    @SuppressWarnings("unchecked")
    public static boolean isValidGuestPath(String path) {
        if (MODE.equals("new")) {
            return (Boolean) rustanything.TerminalRsNative.call_isValidGuestPath(path);
        }
        boolean expected = PortableLogicKt.isValidGuestPath(path);
        if (!MODE.equals("old")) {
            Object actual;
            try {
                actual = rustanything.TerminalRsNative.call_isValidGuestPath(path);
            } catch (RuntimeException e) {
                actual = e;
            }
            compare("isValidGuestPath", expected, actual);
        }
        return expected;
    }

    @SuppressWarnings("unchecked")
    public static String nameSafe(String id) {
        if (MODE.equals("new")) {
            return (String) rustanything.TerminalRsNative.call_nameSafe(id);
        }
        String expected = PortableLogicKt.nameSafe(id);
        if (!MODE.equals("old")) {
            Object actual;
            try {
                actual = rustanything.TerminalRsNative.call_nameSafe(id);
            } catch (RuntimeException e) {
                actual = e;
            }
            compare("nameSafe", expected, actual);
        }
        return expected;
    }

    @SuppressWarnings("unchecked")
    public static boolean isNewer(String latest, String installed) {
        if (MODE.equals("new")) {
            return (Boolean) rustanything.TerminalRsNative.call_isNewer(latest, installed);
        }
        boolean expected = PortableLogicKt.isNewer(latest, installed);
        if (!MODE.equals("old")) {
            Object actual;
            try {
                actual = rustanything.TerminalRsNative.call_isNewer(latest, installed);
            } catch (RuntimeException e) {
                actual = e;
            }
            compare("isNewer", expected, actual);
        }
        return expected;
    }
}
